"""Monta um relatório transportável com as prévias e quadros do ensaio."""
from pathlib import Path
import base64, json, html, statistics
base=Path(__file__).resolve().parents[2]/'docs/experimentos-2026-10-29'
def data(p,mime):return 'data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()
nomes={'mecanismo':('Mecanismo em corte','Aproximação pela geometria alvo, rótulo completo e faces internas visíveis. O modelo geométrico é o mesmo; o filamento continua esquemático.'),'pixel':('Pixel com objeto','O café acompanha a mão até a boca e retorna. A identidade do item e os valores de HUD são preservados.'),'escala':('Explicação 2D de escala','Comprimentos 1:2:4 no mesmo eixo e unidade. A base ignora esse novo tipo de esquema e mostra uma cadeia sem proporções.')}
parts=['''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>videos-auto · ensaios visuais</title><style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#101823;color:#e7edf6}body{max-width:1120px;margin:auto;padding:28px}h1{font-size:clamp(26px,4vw,46px)}p{line-height:1.6;max-width:85ch;color:#bfcede}section{margin:36px 0;padding:24px;border:1px solid #344558;border-radius:16px;background:#162131}.pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}video,img{width:100%;display:block;border-radius:8px;background:#080c12}.videos{max-width:760px;margin:auto}.videos video{max-height:65vh}h3{margin:12px 0}button{background:#ffdc8a;color:#101823;border:0;border-radius:6px;padding:10px 15px;font-weight:bold;cursor:pointer}input{width:min(60%,500px);vertical-align:middle}small{color:#adc0d5}a{color:#8fd3ff}table{border-collapse:collapse;width:100%}td,th{text-align:left;border-bottom:1px solid #344558;padding:8px}summary{cursor:pointer;padding:12px}code{overflow-wrap:anywhere}@media(max-width:600px){body{padding:12px}section{padding:12px}.pair{gap:8px}h3{font-size:15px}}
</style><h1>Três ensaios para evoluir os motores</h1><p>Comparação com a produção de 29/10/2026 (<code>358566f</code>). Os pares usam o mesmo spec, duração e instantes. O candidato acrescenta capacidades ao motor; nenhum vídeo foi publicado. Estes ensaios não demonstram equivalência aos canais de referência.</p><p>Prévias sem áudio: seis segundos, 12 fps e 540 × 960. Quadros de inspeção: 1080 × 1920. Nos clipes, apenas o 3D usa resolução interna de 50%, igualmente na base e no candidato; a composição preserva a grade original. O padrão de produção permanece em 30 fps. O tempo de render local foi registrado com outras tarefas concorrentes; não serve como benchmark isolado de desempenho.</p>''']
metrics={}
for tipo in ['antes','depois']:metrics[tipo]={x['nome']:x for x in json.loads((base/tipo/'resultados.json').read_text())}
for key,(titulo,explicacao) in nomes.items():
 parts += [f'<section data-pair><h2>{titulo}</h2><p>{explicacao}</p><div class="pair videos">']
 for tipo in ['antes','depois']:
  parts += [f'<div><h3>{tipo.capitalize()}</h3><video preload="metadata" playsinline controls src="{data(base/tipo/(key+".mp4"),"video/mp4")}"></video></div>']
 parts += ['</div><p><button type="button" class="play">Reproduzir os dois</button> <input aria-label="Instante dos dois vídeos" type="range" min="0" max="5.916" step="0.083333" value="0"><output>0,00 s</output></p>']
 parts += ['<details><summary>Quadro em 4,5 segundos</summary><div class="pair">']
 for tipo in ['antes','depois']:
  parts += [f'<div><h3>{tipo.capitalize()}</h3><img loading="lazy" alt="{titulo}, {tipo}, 4,5 segundos" src="{data(base/tipo/(key+"-4.5.png"),"image/png")}"></div>']
 parts += ['</div></details><table><tr><th>Conferência técnica</th><th>Antes</th><th>Depois</th></tr>']
 for label,field in [('Erros no navegador','erros'),('Quadro repetido idêntico','quadro_repetido_identico')]:
  parts += [f'<tr><td>{label}</td>'+''.join(f'<td>{html.escape(str(metrics[t][key][field]))}</td>' for t in ['antes','depois'])+'</tr>']
 parts += ['</table></section>']
parts+=['''<h2>Referências e limites</h2><p>Enquadramento e revelação de interior: vídeos locais fornecidos pelo usuário, quadros extraídos em 12 s e 10 s das gravações de 26/10. Referências de estudo: <a href="https://www.branch.education/videos">Branch Education</a>, <a href="https://jaredowen3d.com/">Jared Owen</a>, <a href="https://saint11.art/pixel_art_articles/">Saint11</a>, <a href="https://upponhill.com/">AdamCYounis</a>, <a href="https://kurzgesagt.org/what-we-do?visit=videos">Kurzgesagt</a> e <a href="https://www.youtube.com/watch?v=rbu7Zu5X1zI">3Blue1Brown</a>. O catálogo verificou páginas e descrições; não houve análise integral desses vídeos externos nem atribuição fictícia de timecodes.</p><p>O desenho de escala precisa de valores positivos reais e uma unidade comum. Dados ausentes são bloqueados pelo preflight; entrada direta no palco mantém uma apresentação qualitativa sem inventar medidas. Os prompts canônicos locais foram atualizados; a produção e o n8n não foram alterados por este ensaio.</p><script>
document.querySelectorAll('[data-pair]').forEach(group=>{const videos=[...group.querySelectorAll('video')],range=group.querySelector('input'),out=group.querySelector('output'),btn=group.querySelector('.play');range.addEventListener('input',()=>{videos.forEach(v=>{v.pause();v.currentTime=Number(range.value)});out.value=Number(range.value).toFixed(2).replace('.',',')+' s';btn.textContent='Reproduzir os dois'});btn.addEventListener('click',async()=>{if(videos.some(v=>!v.paused)){videos.forEach(v=>v.pause());btn.textContent='Reproduzir os dois';return}if(videos[0].ended){videos.forEach(v=>v.currentTime=0)}else videos[1].currentTime=videos[0].currentTime;await Promise.all(videos.map(v=>v.play().catch(()=>{})));btn.textContent='Pausar os dois'});videos[0].addEventListener('timeupdate',()=>{range.value=videos[0].currentTime;out.value=videos[0].currentTime.toFixed(2).replace('.',',')+' s';if(!videos[0].paused&&!videos[1].paused&&Math.abs(videos[0].currentTime-videos[1].currentTime)>.15)videos[1].currentTime=videos[0].currentTime});videos[0].addEventListener('ended',()=>{videos.forEach(v=>v.pause());btn.textContent='Reproduzir os dois'})});
</script></html>''']
(base/'index.html').write_text('\n'.join(parts))
print('Galeria independente:',base/'index.html')
